insert into public.content_documents (collection, key, data, sort_order) values ('cities', 'leipzig', $seed${"slug":"leipzig","name":"Leipzig","lastVerified":"2026-11-05","facts":[{"label":{"en":"Studentenwerk dorm, all-inclusive","ne":"Studentenwerk छात्रावास, सबै समावेश","hi":"Studentenwerk हॉस्टल, सब शामिल"},"value":{"en":"€215–435 a month · average €310","ne":"महिनामा €२१५–४३५ · औसत €३१०","hi":"हर महीने €215–435 · औसत €310"}},{"label":{"en":"Asking rent for new contracts","ne":"नयाँ सम्झौताको माग गरिएको भाडा","hi":"नए अनुबंधों का मांगा गया किराया"},"value":{"en":"about €9.26 per m², before heating (2024)","ne":"प्रति वर्गमिटर करिब €९.२६, तताउने बाहेक (२०२४)","hi":"प्रति वर्ग मीटर लगभग €9.26, हीटिंग के बिना (2024)"}},{"label":{"en":"Semester fee, Leipzig University","ne":"सेमेस्टर शुल्क, लाइपजिग विश्वविद्यालय","hi":"सेमेस्टर फ़ीस, लाइपज़िग विश्वविद्यालय"},"value":{"en":"€332.30 (winter 2026/27), incl. Deutschland-Semesterticket","ne":"€३३२.३० (जाडो २०२६/२७), Deutschland-Semesterticket सहित","hi":"€332.30 (शीतकालीन 2026/27), Deutschland-Semesterticket सहित"}},{"label":{"en":"Deutschlandticket","ne":"Deutschlandticket","hi":"Deutschlandticket"},"value":{"en":"€63 a month · €66.80 from 2027","ne":"महिनाको €६३ · २०२७ देखि €६६.८०","hi":"हर महीने €63 · 2027 से €66.80"}},{"label":{"en":"Living costs, university estimate","ne":"जीवनयापन खर्च, विश्वविद्यालयको अनुमान","hi":"रहने का ख़र्च, विश्वविद्यालय का अनुमान"},"value":{"en":"about €1,000 a month incl. rent","ne":"भाडासहित महिनामा करिब €१,०००","hi":"किराए सहित हर महीने लगभग €1,000"}},{"label":{"en":"City service hotline","ne":"सहर सेवा हटलाइन","hi":"शहर सेवा हॉटलाइन"},"value":{"en":"115","ne":"११५","hi":"115"}}],"appointments":[{"title":{"en":"Citizens’ office · Bürgerbüro","ne":"नागरिक कार्यालय · Bürgerbüro","hi":"नागरिक कार्यालय · Bürgerbüro"},"body":{"en":"Book online or call 115. Any Bürgerbüro can register you. New slots appear daily at 8:00 (Otto-Schill-Straße also at 12:00). Otto-Schill-Straße 2: Mon, Tue, Thu, Fri 8–19, Wed 8–12 and 16–19, Sat 8–13.","ne":"अनलाइन बुक गर्नुहोस् वा ११५ मा फोन गर्नुहोस्। जुनसुकै Bürgerbüro ले दर्ता गर्छ। नयाँ समय दैनिक ८:०० बजे खुल्छ (Otto-Schill-Straße मा १२:०० बजे पनि)। Otto-Schill-Straße 2: सोम, मंगल, बिहि, शुक्र ८–१९, बुध ८–१२ र १६–१९, शनि ८–१३।","hi":"ऑनलाइन बुक करें या 115 पर कॉल करें। कोई भी Bürgerbüro पंजीकरण करता है। नए स्लॉट रोज़ 8:00 बजे खुलते हैं (Otto-Schill-Straße में 12:00 बजे भी)। Otto-Schill-Straße 2: सोम, मंगल, गुरु, शुक्र 8–19, बुध 8–12 और 16–19, शनि 8–13।"},"url":"https://terminvereinbarung.leipzig.de"},{"title":{"en":"Foreigners’ office · Ausländerbehörde","ne":"विदेशी कार्यालय · Ausländerbehörde","hi":"विदेशी कार्यालय · Ausländerbehörde"},"body":{"en":"Residence permits for studies are applied for online — you are invited by email for biometrics. Technisches Rathaus, Prager Straße 126–128, 04317 Leipzig · 0341 123-3310.","ne":"पढाइका लागि आवास अनुमतिपत्रको आवेदन अनलाइन दिइन्छ — बायोमेट्रिकका लागि इमेलबाट बोलाइन्छ। Technisches Rathaus, Prager Straße 126–128, 04317 Leipzig · ०३४१ १२३-३३१०।","hi":"पढ़ाई के निवास परमिट का आवेदन ऑनलाइन होता है — बायोमेट्रिक के लिए ईमेल से बुलाया जाता है। Technisches Rathaus, Prager Straße 126–128, 04317 Leipzig · 0341 123-3310।"},"url":"https://www.leipzig.de/service-portal/formulare/onlineantrag-aufenthalt-zu-ausbildung-studium-berufsanerkennung"},{"title":{"en":"Welcome Centre · Willkommenszentrum","ne":"स्वागत केन्द्र · Willkommenszentrum","hi":"स्वागत केंद्र · Willkommenszentrum"},"body":{"en":"Free first advice for newcomers in several languages: residence, work, language courses, everyday life. Otto-Schill-Straße 2, 04109 Leipzig · 0341 123-2676.","ne":"नयाँ आउनेहरूका लागि धेरै भाषामा निःशुल्क प्रारम्भिक सल्लाह: बसाइ, काम, भाषा कक्षा, दैनिक जीवन। Otto-Schill-Straße 2, 04109 Leipzig · ०३४१ १२३-२६७६।","hi":"नए लोगों के लिए कई भाषाओं में मुफ़्त शुरुआती सलाह: निवास, काम, भाषा कोर्स, रोज़मर्रा का जीवन। Otto-Schill-Straße 2, 04109 Leipzig · 0341 123-2676।"},"url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/welcome-centre-leipzig"}],"community":[{"name":"Willkommenszentrum Leipzig","kind":{"en":"Advice","ne":"सल्लाह","hi":"सलाह"},"description":{"en":"The city’s first stop for newcomers. Free.","ne":"नयाँ आउनेहरूका लागि सहरको पहिलो ठाउँ। निःशुल्क।","hi":"नए लोगों के लिए शहर का पहला पड़ाव। मुफ़्त।"},"address":"Otto-Schill-Straße 2, 04109 Leipzig","phone":"+49 341 1232676","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/welcome-centre-leipzig"},{"name":"Studentenwerk Leipzig — International student support","kind":{"en":"Students","ne":"विद्यार्थी","hi":"छात्र"},"description":{"en":"Free social counselling for international students in several languages: money, housing, jobs.","ne":"अन्तर्राष्ट्रिय विद्यार्थीका लागि धेरै भाषामा निःशुल्क सामाजिक परामर्श: पैसा, आवास, काम।","hi":"अंतरराष्ट्रीय छात्रों के लिए कई भाषाओं में मुफ़्त सामाजिक परामर्श: पैसा, आवास, नौकरी।"},"url":"https://www.studentenwerk-leipzig.de/en/counselling-social-issues/social-counselling/international-student-support/"},{"name":"Caritas Leipzig — Migrationsberatung","kind":{"en":"Migration advice","ne":"आप्रवासन सल्लाह","hi":"प्रवासन सलाह"},"description":{"en":"Free migration counselling for adults (MBE).","ne":"वयस्कका लागि निःशुल्क आप्रवासन परामर्श (MBE)।","hi":"वयस्कों के लिए मुफ़्त प्रवासन परामर्श (MBE)।"},"address":"Ruth-Pfau-Straße 2, 04107 Leipzig","phone":"+49 341 9636125","url":"https://www.caritas-leipzig.de/hilfeundberatung/migrationundintegration/migrationsberatung/migrationsberatung"},{"name":"Diakonie Leipzig — Jugendmigrationsdienst Naomi","kind":{"en":"Under 27","ne":"२७ वर्षमुनि","hi":"27 से कम उम्र"},"description":{"en":"Free migration counselling for young people aged 12–27.","ne":"१२–२७ वर्षका युवाका लागि निःशुल्क आप्रवासन परामर्श।","hi":"12–27 साल के युवाओं के लिए मुफ़्त प्रवासन परामर्श।"},"address":"Eisenbahnstraße 66, 04315 Leipzig","phone":"+49 341 68709124","url":"https://www.diakonie-leipzig.de/hilfe-angebote/beratung-nothilfe/naomi-jugendmigrationsberatung/"},{"name":"Mieterverein Leipzig","kind":{"en":"Housing","ne":"आवास","hi":"आवास"},"description":{"en":"Tenants’ association: checks contracts and bills for members.","ne":"भाडावाल संघ: सदस्यका लागि सम्झौता र बिल जाँच्छ।","hi":"किरायेदार संघ: सदस्यों के लिए अनुबंध और बिल जांचता है।"},"phone":"+49 341 2131277","url":"https://www.mieterverein-leipzig.de/mitgliedschaft/"}],"budget":[{"label":{"en":"Rent (dorm average, all-inclusive)","ne":"भाडा (छात्रावास औसत, सबै समावेश)","hi":"किराया (हॉस्टल औसत, सब शामिल)"},"value":310},{"label":{"en":"Health insurance (student rate)","ne":"स्वास्थ्य बीमा (विद्यार्थी दर)","hi":"स्वास्थ्य बीमा (छात्र दर)"},"value":141},{"label":{"en":"Food and everyday costs","ne":"खाना र दैनिक खर्च","hi":"खाना और रोज़मर्रा का ख़र्च"},"value":300},{"label":{"en":"Semester fee incl. ticket (per month)","ne":"टिकटसहित सेमेस्टर शुल्क (प्रति महिना)","hi":"टिकट सहित सेमेस्टर फ़ीस (प्रति माह)"},"value":55},{"label":{"en":"Study materials","ne":"पढाइ सामग्री","hi":"पढ़ाई का सामान"},"value":70},{"label":{"en":"Broadcasting fee","ne":"प्रसारण शुल्क","hi":"प्रसारण शुल्क"},"value":18}],"sources":[{"title":"Stadt Leipzig — Bürgerbüros","url":"https://www.leipzig.de/buergerservice-und-verwaltung/aemter-und-behoerdengaenge/buergerbueros/"},{"title":"Stadt Leipzig — Bürgerbüro Otto-Schill-Straße","url":"https://www.leipzig.de/service-portal/dienststelle/buergeramt-stadthaus-10007011"},{"title":"City of Leipzig — Foreigners’ Authority","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/foreigners-authority"},{"title":"City of Leipzig — Welcome Centre","url":"https://english.leipzig.de/youth-family-and-community/foreign-nationals-and-migrants/welcome-centre-leipzig"},{"title":"Studentenwerk Leipzig — Housing survey 2026 (PDF)","url":"https://www.studentenwerk-leipzig.de/ext/uploads/2026/04/Ergebnisbericht_Wohnen_Studentenwerk_Leipzig.pdf"},{"title":"S