insert into public.content_documents (collection, key, data, sort_order) values ('ruleChanges', 'rc-2027-wage', $seed${"id":"rc-2027-wage","date":"2027-01-01","affects":{"statuses":["student","trainee","worker"]},"title":{"en":"Minimum wage and mini-job limit rise in 2027","ne":"२०२७ मा न्यूनतम ज्याला र मिनी-जब सीमा बढ्छ","hi":"2027 में न्यूनतम वेतन और मिनी-जॉब सीमा बढ़ेगी"},"summary":{"en":"From 1 January 2027 the minimum wage rises from €13.90 to €14.60 an hour, and the mini-job limit from €603 to €633 a month.","ne":"१ जनवरी २०२७ देखि न्यूनतम ज्याला प्रतिघण्टा €१३.९० बाट €१४.६० र मिनी-जब सीमा महिनामा €६०३ बाट €६३३ हुन्छ।","hi":"1 जनवरी 2027 से न्यूनतम वेतन €13.90 से बढ़कर €14.60 प्रति घंटा, और मिनी-जॉब सीमा €603 से बढ़कर €633 प्रति माह होगी।"},"guideSlug":"student-jobs","sources":[{"title":"Deutsche Rentenversicherung — Mini-job earnings limit rises to €603","url":"https://www.deutsche-rentenversicherung.de/BadenWuerttemberg/DE/Presse/Pressemitteilungen/2025/251222_Minijob.html"}]}$seed$::jsonb, 0) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('ruleChanges', 'rc-2027-dticket', $seed${"id":"rc-2027-dticket","date":"2027-01-01","affects":{},"title":{"en":"Deutschlandticket costs €66.80 from 2027","ne":"२०२७ देखि Deutschlandticket €६६.८०","hi":"2027 से Deutschlandticket €66.80"},"summary":{"en":"The monthly price rises from €63 to €66.80 on 1 January 2027. Students with the Deutschland-Semesterticket pay through their semester fee.","ne":"१ जनवरी २०२७ देखि मासिक मूल्य €६३ बाट €६६.८० हुन्छ। Deutschland-Semesterticket भएका विद्यार्थीले सेमेस्टर शुल्कमार्फत तिर्छन्।","hi":"1 जनवरी 2027 से मासिक कीमत €63 से बढ़कर €66.80 होगी। Deutschland-Semesterticket वाले छात्र सेमेस्टर फ़ीस से भरते हैं।"},"guideSlug":"monthly-transit-pass","sources":[{"title":"Deutsche Bahn — The Deutschland-Ticket (€63, €66.80 from 2027)","url":"https://int.bahn.de/en/offers/regional/deutschland-ticket"},{"title":"Federal Government — Deutschlandticket questions and answers","url":"https://www.bundesregierung.de/breg-de/aktuelles/deutschlandticket-2134074"}]}$seed$::jsonb, 10) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('ruleChanges', 'rc-2026-leipzig-fee', $seed${"id":"rc-2026-leipzig-fee","date":"2026-10-01","affects":{"statuses":["student"],"cities":["leipzig"]},"title":{"en":"Higher semester fee at Leipzig University","ne":"लाइपजिग विश्वविद्यालयमा सेमेस्टर शुल्क बढ्यो","hi":"लाइपज़िग विश्वविद्यालय में सेमेस्टर फ़ीस बढ़ी"},"summary":{"en":"From the winter semester 2026/27 the fee is €332.30 (before: €312.30), because the Deutschland-Semesterticket now costs €226.80.","ne":"२०२६/२७ जाडो सेमेस्टरदेखि शुल्क €३३२.३० (पहिले: €३१२.३०) भएको छ, किनभने Deutschland-Semesterticket अब €२२६.८० पर्छ।","hi":"शीतकालीन सेमेस्टर 2026/27 से फ़ीस €332.30 (पहले: €312.30) है, क्योंकि Deutschland-Semesterticket अब €226.80 का है।"},"guideSlug":"enrol-at-university","sources":[{"title":"Leipzig University — Overview of semester fees (PDF)","url":"https://www.uni-leipzig.de/fileadmin/ul/Dokumente/260413_StudSek_%C3%9Cbersicht_Semesterbeitr%C3%A4ge.pdf"},{"title":"Studentenwerk Leipzig — Price increase for the semester ticket (PDF)","url":"https://www.studentenwerk-leipzig.de/ext/uploads/2026/02/26-02-12-Preiserhoehung-fuer-Deutschland-Semesterticket-und-Co.-%E2%80%93-studentische-Mobilitaet-in-Leipzig-wird-teurer.pdf"}]}$seed$::jsonb, 20) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('ruleChanges', 'rc-2026-wage', $seed${"id":"rc-2026-wage","date":"2026-01-01","affects":{"statuses":["student","trainee","worker"]},"title":{"en":"New minimum wage and mini-job limit","ne":"नयाँ न्यूनतम ज्याला र मिनी-जब सीमा","hi":"नया न्यूनतम वेतन और मिनी-जॉब सीमा"},"summary":{"en":"Since 1 January 2026 the minimum wage is €13.90 an hour and you can earn up to €603 a month in a mini-job.","ne":"१ जनवरी २०२६ देखि न्यूनतम ज्याला प्रतिघण्टा €१३.९० छ र मिनी-जबमा महिनामा €६०३ सम्म कमाउन सकिन्छ।","hi":"1 जनवरी 2026 से न्यूनतम वेतन €13.90 प्रति घंटा है और मिनी-जॉब में हर महीने €603 तक कमा सकते हैं।"},"guideSlug":"student-jobs","sources":[{"title":"Deutsche Rentenversicherung — Mini-job earnings limit rises to €603","url":"https://www.deutsche-rentenversicherung.de/BadenWuerttemberg/DE/Presse/Pressemitteilungen/2025/251222_Minijob.html"},{"title":"Minijob-Zentrale — Students","url":"https://www.minijob-zentrale.de/DE/die-minijobs/studenten/studenten_node.html"}]}$seed$::jsonb, 30) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('ruleChanges', 'rc-2026-tax', $seed${"id":"rc-2026-tax","date":"2026-01-01","affects":{},"title":{"en":"Tax-free allowance is €12,348","ne":"करमुक्त सीमा €१२,३४८","hi":"टैक्स-मुक्त सीमा €12,348"},"summary":{"en":"For 2026 the first €12,348 of income is tax-free (2025: €12,096). Students with small jobs often get all wage tax back with a tax return.","ne":"२०२६ का लागि पहिलो €१२,३४८ आम्दानी करमुक्त छ (२०२५: €१२,०९६)। सानो काम गर्ने विद्यार्थीले कर विवरण बुझाएर प्रायः सबै तलब कर फिर्ता पाउँछन्।","hi":"2026 के लिए पहले €12,348 की आय टैक्स-मुक्त है (2025: €12,096)। छोटी नौकरी वाले छात्रों को टैक्स रिटर्न से अक्सर पूरा वेतन टैक्स वापस मिलता है।"},"guideSlug":"file-tax-return","sources":[{"title":"Federal Ministry of Finance — Main tax changes 2026 (basic allowance €12,348)","url":"https://www.bundesfinanzministerium.de/Monatsberichte/Ausgabe/2026/02/Inhalte/Kapitel-2-Analysen/2-5-wichtigste-steuerliche-aenderungen-2026.html"}]}$seed$::jsonb, 40) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('ruleChanges', 'rc-2026-india-saxony', $seed${"id":"rc-2026-india-saxony","date":"2026-01-20","affects":{"nationalities":["india"],"cities":["leipzig"]},"title":{"en":"Saxony: consular services from the Embassy in Berlin","ne":"सक्सोनी: बर्लिनस्थित दूतावासबाट कन्सुलर सेवा","hi":"सैक्सनी: बर्लिन दूतावास से कांसुलर सेवाएं"},"summary":{"en":"Indian citizens living in Saxony get passport and consular services from the Embassy of India in Berlin. Appointments are booked online.","ne":"सक्सोनीमा बस्ने भारतीय नागरिकले राहदानी र कन्सुलर सेवा बर्लिनस्थित भारतीय दूतावासबाट पाउँछन्। अपोइन्टमेन्ट अनलाइन बुक गरिन्छ।","hi":"सैक्सनी में रहने वाले भारतीय नागरिकों को पासपोर्ट और कांसुलर सेवाएं बर्लिन स्थित भारतीय दूतावास से मिलती हैं। अपॉइंटमेंट ऑनलाइन बुक होते हैं।"},"sources":[{"title":"Embassy of India, Berlin — Consular jurisdiction (PDF)","url":"https://indianembassyberlin.gov.in/pdf/passport_Jurisdiction_Berlin.pdf"},{"title":"Embassy of India, Berlin — Online appointments","url":"https://appointment.indianembassyberlin.gov.in/"}]}$seed$::jsonb, 50) on conflict (collection, key) do nothing;
insert into public.content_documents (collection, key, data, sort_order) values ('providers', 'coracle', $seed${"id":"coracle","category":"blocked","name":"Coracle","setupFee":"€99","monthlyFee":"€0","openingTime":"","payout":"","facts":[{"en":"One-time fee, no monthly fee","ne":"एकपटकको शुल्क, मासिक शुल्क छैन","hi":"एक बार की फ़ीस, कोई मासिक फ़ीस नहीं"},{"en":"€50 fee if you close early and get the money back (e.g. visa refused)","ne":"चाँडै बन्द गरी पैसा फिर्ता लिँदा €५० शुल्क (जस्तै भिसा अस्वीकृत)","hi":"जल्दी बंद करके पैसा वापस लेने पर €50 फ़ीस (जैसे वीज़ा अस्वीकार)"},{"en":"Fees from Coracle’s published terms (2023) — check before you sign up","ne":"Coracle का प्रकाशित सर्तबाट लिइएको शुल्क (२०२३) — दर्ता गर्नुअघि जाँच्नुहोस्","hi":"Coracle की प्रकाशित शर्तों (2023) से फ़ीस — साइन अप से पहले जांचें"}],"isPartner":false,"url":"https://www.coracle.de/","lastChecked":"2026-11-05","feeSortKey":99,"speedSortKey":0,"sources":[{"title":"Coracle — Blocked account (one-time fee)","url":"https://www.coracle.de/blog/is-opening-a-coracle-blocked-account-safe"},{"title":"Coracle — Terms and conditions (PDF)","url":"https://www.coracle.de/ba-terms-and-conditions-coracle_2023.pdf"}]}$seed$::jsonb, 0) on conflict (collection, key) do nothing;
